style.css:
@-moz-document domain("discord.com") {
/* ---------- General ---------- */
    .theme-dark {
        background: linear-gradient(135deg, #0f0f17, #1c0033) !important;
        color: #e0e0ff !important;
        font-family: "Whitney", "Segoe UI", sans-serif !important;
    }

    /* ---------- Server List ---------- */
    .guilds-wrapper {
        background: rgba(20, 0, 50, 0.8) !important;
        border-radius: 15px !important;
        padding: 5px !important;
    }

    .guild-2JjQbA:hover {
        background: rgba(100, 0, 200, 0.3) !important;
        transform: scale(1.05) !important;
        transition: all 0.2s ease !important;
    }

    /* ---------- Channels ---------- */
    .channels-wrap {
        background: rgba(20, 0, 50, 0.8) !important;
        border-radius: 15px !important;
        padding: 10px !important;
    }

    .channel-2QD9_O:hover {
        background: rgba(100, 0, 200, 0.2) !important;
        border-radius: 10px !important;
        transition: all 0.2s ease !important;
    }

    /* ---------- Chat Area ---------- */
    .chat {
        background: linear-gradient(135deg, #1c0033, #2e0066) !important;
        border-radius: 20px !important;
        padding: 15px !important;
    }

    /* ---------- Messages ---------- */
    .message-2qnXI6 {
        background: rgba(70, 0, 150, 0.3) !important;
        border-radius: 15px !important;
        padding: 8px 12px !important;
        margin-bottom: 6px !important;
        transition: transform 0.2s, box-shadow 0.2s !important;
    }

    .message-2qnXI6:hover {
        transform: translateY(-2px) !important;
        box-shadow: 0 4px 15px rgba(100, 0, 200, 0.5) !important;
    }

    /* ---------- Username ---------- */
    .username-1A8OIy {
        background: linear-gradient(90deg, #d383ff, #5c00ff) !important;
        -webkit-background-clip: text !important;
        -webkit-text-fill-color: transparent !important;
        font-weight: bold !important;
    }

    /* ---------- Message Text ---------- */
    .markup-2BOw-j {
        color: #e0e0ff !important;
    }

    /* ---------- Input ---------- */
    .textArea-12jD-V,
    .textArea-12jD-V:focus {
        background: rgba(255, 255, 255, 0.05) !important;
        border-radius: 15px !important;
        color: #fff !important;
        border: none !important;
        padding: 10px !important;
    }

    /* ---------- Scrollbars ---------- */
    .scrollbar-3Y5Sv6, 
    .scrollbar-3Y5Sv6::-webkit-scrollbar-thumb {
        width: 8px !important;
        background: rgba(100, 0, 200, 0.2) !important;
        border-radius: 10px !important;
    }

    /* ---------- Buttons ---------- */
    .button-38aScr {
        background: linear-gradient(135deg, #5c00ff, #d383ff) !important;
        border-radius: 12px !important;
        color: #fff !important;
        font-weight: bold !important;
        transition: all 0.2s ease !important;
    }

    .button-38aScr:hover {
        filter: brightness(1.2) !important;
        transform: scale(1.05) !important;
    }

    /* ---------- Popups / Tooltips ---------- */
    .popout-3qk4J9,
    .tooltip-1AXISb {
        background: rgba(30, 0, 60, 0.9) !important;
        border-radius: 12px !important;
        color: #fff !important;
        box-shadow: 0 4px 20px rgba(100, 0, 200, 0.4) !important;
    }

    /* ---------- Modals ---------- */
    .modal-2LIEKY {
        background: rgba(40, 0, 80, 0.9) !important;
        border-radius: 20px !important;
        color: #fff !important;
    }

    /* ---------- Code / Quotes ---------- */
    pre, code, blockquote {
        background: rgba(50,0,100,0.2) !important;
        border-radius: 12px !important;
        padding: 5px 10px !important;
        color: #e0e0ff !important;
        font-family: Consolas, monospace !important;
    }

    /* ---------- Reactions ---------- */
    .reaction-1R0X0z {
        background: rgba(100,0,200,0.3) !important;
        border-radius: 12px !important;
        transition: transform 0.2s ease !important;
    }

    .reaction-1R0X0z:hover {
        transform: scale(1.1) !important;
    }

    /* ---------- Links ---------- */
    a {
        color: #b580ff !important;
        text-decoration: none !important;
    }

    a:hover {
        text-decoration: underline !important;
    }

    /* ---------- Divider Lines ---------- */
    .divider-3KkX7g {
        border-top: 1px solid rgba(180, 128, 255, 0.3) !important;
    }

    /* ---------- Additional Gradients & Effects ---------- */
    /* Mentions */
    .mention-3m0Q2P {
        background: linear-gradient(90deg, #5c00ff, #d383ff) !important;
        color: #fff !important;
        border-radius: 10px !important;
        padding: 2px 5px !important;
    }

    /* Pins */
    .pinnedMessages-2rYgsB {
        background: rgba(120, 0, 220, 0.2) !important;
        border-radius: 15px !important;
        padding: 5px !important;
    }

    /* Emoji hover pop */
    .emoji-1F-YuX:hover {
        transform: scale(1.3) !important;
        transition: transform 0.2s ease !important;
    }

    /* Role color badges */
    .role-3b3o9o {
        background: linear-gradient(135deg, #d383ff, #5c00ff) !important;
        color: #fff !important;
        border-radius: 6px !important;
        padding: 2px 6px !important;
    }

    /* Server Boost / Nitro badges */
    .boostBadge-3kH5Xc {
        background: linear-gradient(135deg, #8b00ff, #d383ff) !important;
        border-radius: 10px !important;
        color: #fff !important;
        padding: 2px 5px !important;
    }

    /* Animated hover for chat scroll area */
    .scroller-2FKFPG:hover {
        box-shadow: inset 0 0 20px rgba(100,0,200,0.5) !important;
        transition: box-shadow 0.3s ease !important;
    }

    /* Tooltip links */
    .tooltip-1AXISb a {
        color: #d383ff !important;
    }
}
